import { readFileSync } from "node:fs";

import { Validator } from "@cfworker/json-schema";

// Generated by `npm run openapi:index` from the live IcePanel OpenAPI spec.
export type QueryParamSpec = {
  name: string;
  type: "string" | "number" | "boolean" | "array" | "object";
  required: boolean;
};

type SpecIndex = {
  operations: Record<
    string,
    { query: QueryParamSpec[]; body: Record<string, unknown> | null }
  >;
  components: { schemas: Record<string, unknown> };
};

const specIndex = JSON.parse(
  readFileSync(new URL("../generated/icepanel-spec.json", import.meta.url), "utf8"),
) as SpecIndex;

export function operationKey(method: string, pathTemplate: string): string {
  return `${method} ${pathTemplate}`;
}

export function operationSpec(method: string, pathTemplate: string) {
  return specIndex.operations[operationKey(method, pathTemplate)];
}

const validators = new Map<string, Validator | null>();

function validatorFor(key: string): Validator | null {
  if (!validators.has(key)) {
    const body = specIndex.operations[key]?.body;
    // ponytail: refs resolve because components ride along in the same root document.
    validators.set(
      key,
      body
        ? new Validator({ ...body, components: specIndex.components }, "2020-12", false)
        : null,
    );
  }
  return validators.get(key)!;
}

/** Returns human-readable errors, or [] when the body matches the spec (or the op has no body schema). */
export function validateRequestBody(
  method: string,
  pathTemplate: string,
  body: unknown,
): string[] {
  const validator = validatorFor(operationKey(method, pathTemplate));
  if (!validator) {
    return [];
  }
  const result = validator.validate(body);
  return result.errors
    .filter((error) => error.keyword !== "$ref" && error.keyword !== "properties" && error.keyword !== "allOf")
    .map((error) => `${error.instanceLocation}: ${error.error}`);
}
